CREATE DATABASE IF NOT EXISTS `fernosa` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `fernosa`;

CREATE TABLE roles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, slug VARCHAR(80) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, slug VARCHAR(120) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id INT UNSIGNED NULL, username VARCHAR(80) NOT NULL UNIQUE, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(150) NOT NULL, must_change_password TINYINT(1) NOT NULL DEFAULT 1, failed_attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, locked_until DATETIME NULL, last_login_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, INDEX idx_users_role (role_id), CONSTRAINT fk_users_role FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE role_permissions (role_id INT UNSIGNED NOT NULL, permission_id INT UNSIGNED NOT NULL, PRIMARY KEY(role_id, permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, parent_id INT UNSIGNED NULL, title_fa VARCHAR(150) NOT NULL, title_en VARCHAR(150) NULL, slug VARCHAR(180) NOT NULL UNIQUE, description TEXT NULL, icon VARCHAR(80) NULL, color CHAR(7) NOT NULL DEFAULT '#988C75', ordering INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, INDEX idx_categories_parent (parent_id), FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE menu_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id INT UNSIGNED NULL, title_fa VARCHAR(180) NOT NULL, title_en VARCHAR(180) NULL, slug VARCHAR(200) NOT NULL UNIQUE, description_short VARCHAR(500) NULL, description_full TEXT NULL, price DECIMAL(12,2) NOT NULL DEFAULT 0, old_price DECIMAL(12,2) NULL, discount_percent DECIMAL(5,2) NULL, is_available TINYINT(1) NOT NULL DEFAULT 1, is_special TINYINT(1) NOT NULL DEFAULT 0, is_new TINYINT(1) NOT NULL DEFAULT 0, is_best_seller TINYINT(1) NOT NULL DEFAULT 0, is_vegan TINYINT(1) NOT NULL DEFAULT 0, is_spicy TINYINT(1) NOT NULL DEFAULT 0, calories INT UNSIGNED NULL, allergens VARCHAR(500) NULL, ingredients TEXT NULL, ordering INT NOT NULL DEFAULT 0, seo_title VARCHAR(255) NULL, seo_desc VARCHAR(500) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, INDEX idx_items_category(category_id), INDEX idx_items_available(is_available), FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE item_images (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, item_id INT UNSIGNED NOT NULL, file_path VARCHAR(255) NOT NULL, alt_text VARCHAR(255) NULL, ordering INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, INDEX idx_item_images_item(item_id), FOREIGN KEY(item_id) REFERENCES menu_items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE tags (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title_fa VARCHAR(100) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, color CHAR(7) NOT NULL DEFAULT '#988C75', icon VARCHAR(80) NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE item_tags (item_id INT UNSIGNED NOT NULL, tag_id INT UNSIGNED NOT NULL, PRIMARY KEY(item_id, tag_id), FOREIGN KEY(item_id) REFERENCES menu_items(id) ON DELETE CASCADE, FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE special_offers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, item_id INT UNSIGNED NOT NULL, title VARCHAR(180) NULL, discount_price DECIMAL(12,2) NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, FOREIGN KEY(item_id) REFERENCES menu_items(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE pages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(120) NOT NULL UNIQUE, title_fa VARCHAR(180) NOT NULL, title_en VARCHAR(180) NULL, content_fa LONGTEXT NULL, content_en LONGTEXT NULL, seo_title VARCHAR(255) NULL, seo_desc VARCHAR(500) NULL, is_published TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE gallery (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(180) NULL, alt_text VARCHAR(255) NULL, file_path VARCHAR(255) NOT NULL, category VARCHAR(100) NULL, ordering INT NOT NULL DEFAULT 0, is_featured TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE media (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, file_name VARCHAR(255) NOT NULL, file_path VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, file_size INT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE settings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, setting_key VARCHAR(120) NOT NULL UNIQUE, setting_value TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE theme_settings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, setting_key VARCHAR(120) NOT NULL UNIQUE, setting_value VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE branches (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, address TEXT NULL, phone VARCHAR(80) NULL, map_lat DECIMAL(10,7) NULL, map_lng DECIMAL(10,7) NULL, opening_hours JSON NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE qr_codes (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id INT UNSIGNED NULL, table_number VARCHAR(50) NULL, code VARCHAR(120) NOT NULL UNIQUE, scan_count INT UNSIGNED NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE visits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, path VARCHAR(255) NOT NULL, item_id INT UNSIGNED NULL, qr_code_id INT UNSIGNED NULL, visited_on DATE NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_visits_date(visited_on), FOREIGN KEY(item_id) REFERENCES menu_items(id) ON DELETE SET NULL, FOREIGN KEY(qr_code_id) REFERENCES qr_codes(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE contact_messages (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(190) NULL, phone VARCHAR(80) NULL, message TEXT NOT NULL, is_read TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(120) NOT NULL, entity_type VARCHAR(80) NULL, entity_id INT UNSIGNED NULL, ip_address VARCHAR(45) NULL, user_agent VARCHAR(500) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_activity_user(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
